public async Task<string> GetWeatherAsync(string city)
{
    using var client = new HttpClient();
    // Each call creates a new socket connection
    var response = await client.GetAsync($"https://api.weather.com/{city}");
    response.EnsureSuccessStatusCode();
    return await response.Content.ReadAsStringAsync();
}

// Program.cs
builder.Services.AddHttpClient<IWeatherClient, WeatherClient>(client =>
{
    client.BaseAddress = new Uri("https://api.weather.com/");
    client.Timeout = TimeSpan.FromSeconds(10);
});

// WeatherClient.cs
public class WeatherClient : IWeatherClient
{
    private readonly HttpClient _httpClient;

    public WeatherClient(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    public async Task<string> GetWeatherAsync(string city)
    {
        var response = await _httpClient.GetAsync(city);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadAsStringAsync();
    }
}
